#define SHADER "#include <metal_stdlib>\nusing namespace metal;\nstruct V{float4 p [[position]];};\nvertex V vert(uint i [[vertex_id]]){float2 p=float2((i<<1)&2,i&2);return {float4(p*2-1,0,1)};}\nfloat2 rot(float2 p,float a){return float2(cos(a)*p.x-sin(a)*p.y,sin(a)*p.x+cos(a)*p.y);}\nfloat3 pal(float x){return .5+.5*cos(6.283185*(x+float3(0.,.33,.67)));}\nfloat ln(float d,float w){return w/(abs(d)+w);}\nfragment float4 frag(V v [[stage_in]],constant float3 &u [[buffer(0)]]){\n float t=u.z;float2 uv=(v.p.xy*2-u.xy)/u.y;float r=length(uv);float scene=floor(t/32.),lt=fmod(t,32.);float3 c=0.;\n if(scene<1.){float2 p=rot(uv,t*.07);float q=sin(p.x*5.+sin(p.y*4.-lt*.25))*cos(p.y*6.-lt*.3);float bands=ln(abs(fract((q+1.)*5.)-.5),.035);c+=pal(q*.15+lt*.02)*bands*.2;for(int i=0;i<17;i++){float f=float(i),a=f*2.399+lt*(.12+.004*f),rr=fract(f*.618+lt*.018)*.9;float2 z=p-float2(cos(a),sin(a))*rr;float d=length(z);c+=pal(f*.08+lt*.018)*(.004/(d+.006)+exp(-d*18.)*.012);}}else if(scene<2.){for(int i=0;i<24;i++){float f=float(i),a=f*2.399+lt*(.16+.003*f);float2 ctr=float2(.95*sin(a),.6*cos(a*1.2));float2 q=rot(uv-ctr,a+lt*.1);float d=abs(max(abs(q.x)-.035,abs(q.y)-.035));c+=pal(f*.05+lt*.02)*ln(d,.003)*.035;}float wave=abs(length(uv)-(.3+.12*sin(atan2(uv.y,uv.x)*5.+lt*.2)));c+=pal(lt*.025)*ln(wave,.005)*.07;}else{float2 p=rot(uv,t*.04);for(int i=0;i<12;i++){float f=float(i);float a=atan2(p.y,p.x)+f*.13;float d=abs(length(p)-(.12+f*.095+.035*sin(a*4.-lt*.2)));c+=pal(f*.09+lt*.02)*ln(d,.006)*.045;}float n=sin(p.x*4.+lt*.2+sin(p.y*3.-lt*.1));c+=pal(n*.1+lt*.01)*exp(-abs(n-p.y)*12.)*.08;}\n c*=1.-.18*smoothstep(.25,1.7,r);c=1.-exp(-max(c,0.)*1.8);c=pow(c,float3(.82));float fade=smoothstep(0.,2.,t)*(1.-smoothstep(94.,96.,t));c*=fade;return float4(c,1.);}\n"
